/**
 * "Make it official" (redesign-v2 part 4, feature 7; screen 9).
 *
 * REVIEWED STATIC CONTENT — never generated by the AI at runtime. A step's content is shown only
 * when the owner has reviewed it: set `reviewed: true` AND `lastChecked` (the date it was checked
 * against the official page). Until then the page shows "Being reviewed" in its place.
 *
 * Drafted 2026-11-15 from the official sites named in each step, WITHOUT a live re-check of those
 * pages from this environment. Every threshold, fee and eligibility rule is marked
 * `NEEDS OWNER REVIEW` below and listed in `sources` with the page to check it against. The
 * user-facing text deliberately quotes no thresholds or fees: those stay in `sources` until
 * reviewed and then belong in the text only if the owner adds them.
 *
 * Links go to official government sites only.
 */
import type { Locale } from "@/lib/i18n/locale";

/** The roadmap's phase keys, in order (see RoadmapSkeletonSchema). */
export const PHASE_ORDER = [
  "understand",
  "explore",
  "validate",
  "build",
  "launch",
  "improve",
] as const;
export type PhaseKey = (typeof PHASE_ORDER)[number];

export interface StepText {
  title: string;
  /** Plain-language summary. */
  summary: string;
  /** When it is needed, in words (tied to `neededFrom`). */
  when: string;
  documents: string[];
  steps: string[];
}

export interface Source {
  /** The rule, for the reviewer (English). */
  rule: string;
  /** The official page to check it against. */
  url: string;
  needsOwnerReview: boolean;
}

export interface OfficialStep {
  id: "structure" | "udyam" | "bank" | "gst";
  /** Visible from the start; "Not needed yet" until the roadmap reaches this phase. */
  neededFrom: PhaseKey;
  /** Official government site only. */
  officialUrl: string;
  officialName: string;
  /** Set by the owner after review. */
  reviewed: boolean;
  /** ISO date the step was last checked against `sources`; null until reviewed. */
  lastChecked: string | null;
  sources: Source[];
  text: Record<Locale, StepText>;
}

