/** Has the roadmap reached this step's phase? (Roadmaps skip phases that don't apply, so this
 * compares positions in the fixed phase order, not the roadmap's own list.) */
export function isStepNeeded(step: Pick<OfficialStep, "neededFrom">, current: PhaseKey | null) {
  if (!current) return false;
  return PHASE_ORDER.indexOf(current) >= PHASE_ORDER.indexOf(step.neededFrom);
}

/** A step's content is shown only once the owner reviewed it and dated the check. */
export const isStepPublished = (s: Pick<OfficialStep, "reviewed" | "lastChecked">) =>
  s.reviewed && Boolean(s.lastChecked);
